{
  "lines": [
    {
      "id": "reflection.feedback_exercises",
      "tiers": [
        {
          "id": "reflection.feedback_exercises:t1",
          "title": "Микрофон для ощущений",
          "phrase": "Ты оставил отзывы о 2 разных упражнениях. Железо молчит, а ты говоришь по делу.",
          "imagePrompt": "A little kettlebell reporter holds a microphone between an animated dumbbell and a coiled resistance band; the dumbbell leans toward the microphone while the band raises one loop, eagerly waiting for its turn.",
          "fishMarkup": "[warm]Ты оставил отзывы о 2 разных упражнениях. [playful]Железо молчит, а ты говоришь по делу.",
          "audioText": "Ты оставил отзывы о 2 разных упражнениях. Железо молчит, а ты говоришь по делу."
        },
        {
          "id": "reflection.feedback_exercises:t2",
          "title": "Корреспондент между подходами",
          "phrase": "Ты оставил отзывы о 5 разных упражнениях — у ощущений появился собственный пресс-центр.",
          "imagePrompt": "A kettlebell reporter hosts a roundtable with a dumbbell, resistance band, jump rope, exercise mat, and low step; its microphone reaches toward the five animated guests as the mat leans forward with an eager curl.",
          "fishMarkup": "[confident]Ты оставил отзывы о <emphasis>5 разных упражнениях</emphasis> — [playful]у ощущений появился собственный пресс-центр.",
          "audioText": "Ты оставил отзывы о 5 разных упражнениях — у ощущений появился собственный пресс-центр."
        },
        {
          "id": "reflection.feedback_exercises:t3",
          "title": "Железо просит слова",
          "phrase": "Ты оставил отзывы о 10 разных упражнениях. Железо созвало пресс-конференцию — и снова отвечаешь ты!",
          "imagePrompt": "A kettlebell reporter stands on a low exercise step as ten animated workout props lean in with microphones; a towering squat rack stoops to hear the tiny speaker, turning the interview into an unexpectedly crowded press conference.",
          "fishMarkup": "[triumphant]Ты оставил отзывы о <emphasis>10 разных упражнениях</emphasis>. Железо созвало пресс-конференцию — <slow>и снова отвечаешь ты!</slow>",
          "audioText": "Ты оставил отзывы о 10 разных упражнениях. Железо созвало пресс-конференцию — и снова отвечаешь ты!"
        }
      ]
    },
    {
      "id": "reflection.reflection_year",
      "tiers": [
        {
          "id": "reflection.reflection_year:t1",
          "title": "Архив на прогулке",
          "phrase": "Ты собрал 39 недель наблюдений в дневнике ощущений. История растёт в твоём темпе — улитка-архивариус одобряет.",
          "imagePrompt": "A curious snail carries a small clothbound diary as its shell, pausing to inspect a leaf with one raised eyestalk; a short accordion of diary pages trails behind it, holding little pressed leaves from earlier stops.",
          "fishMarkup": "[warm]Ты собрал 39 недель наблюдений в дневнике ощущений. История растёт <soft>в твоём темпе</soft> — [playful]улитка-архивариус одобряет.",
          "audioText": "Ты собрал 39 недель наблюдений в дневнике ощущений. История растёт в твоём темпе — улитка-архивариус одобряет."
        },
        {
          "id": "reflection.reflection_year:t2",
          "title": "Тетрадь раздвигает стены",
          "phrase": "Уже 52 недели наблюдений в твоём дневнике ощущений — ты собрал историю, которой тесно в одной тетради.",
          "imagePrompt": "A snail carries a thick diary shell opened into two great fans of pages; it uses a broad leaf as a reading desk while its eyestalks examine a long accordion insert spilling neatly around its foot.",
          "fishMarkup": "[confident]Уже <emphasis>52 недели наблюдений</emphasis> в твоём дневнике ощущений — [excited]ты собрал историю, которой тесно в одной тетради.",
          "audioText": "Уже 52 недели наблюдений в твоём дневнике ощущений — ты собрал историю, которой тесно в одной тетради."
        },
        {
          "id": "reflection.reflection_year:t3",
          "title": "Читальный зал на спине",
          "phrase": "Ты собрал 78 недель наблюдений в дневнике ощущений. Улитка открывает читальный зал — прямо у себя на спине!",
          "imagePrompt": "A snail's enormous diary shell opens into a reading room with bookshelves and a tiny armchair; the snail curls around to sit inside its own shell, reading a leaf-shaped book while its tail politely holds the door open.",
          "fishMarkup": "[triumphant]Ты собрал <emphasis>78 недель наблюдений</emphasis> в дневнике ощущений. Улитка открывает читальный зал — <slow>прямо у себя на спине!</slow>",
          "audioText": "Ты собрал 78 недель наблюдений в дневнике ощущений. Улитка открывает читальный зал — прямо у себя на спине!"
        }
      ]
    }
  ]
}
